<script setup>
import {computed,reactive,watch} from 'vue'
import {issueLayers,issueStatuses,issueClosures,evidenceLevels,issueRoutes,issueTransitions,newRepairPlan,repairPlan,lines} from '../issue-workflow.js'
const props=defineProps({item:{type:Object,required:true},runs:{type:Array,default:()=>[]},disabled:Boolean})
const emit=defineEmits(['update','navigate'])
const d=reactive({})
watch(()=>props.item,item=>{
  const plan=[...item.events].reverse().find(e=>e.repair_plan)?.repair_plan||item.issue.repair_plan||newRepairPlan(item.issue.sample_id)
  Object.assign(d,{to_status:issueTransitions[item.status][0]||'',note:'',change_summary:'',verification_run_id:'',verification_sample_id:item.issue.sample_id,outcome:'INCONCLUSIVE',closure_type:item.status==='RETESTED'&&item.events.at(-1)?.outcome==='FIXED'?'FIXED':'DEFERRED',evidence_level:'SAME_CASE',target_eliminated:false,regression_checked:false,regression_found:false,regression_result:'',validation_scope:'',unexcluded_factors:'',regression_sample_ids:'',unseen_sample_ids:'',candidate_causes:'',confirmed_cause:'',plan:{...plan},sampleIds:plan.verification_sample_ids.join('\n')})
},{immediate:true})
const canFixed=computed(()=>props.item.status==='RETESTED'&&props.item.events.at(-1)?.outcome==='FIXED')
function submit(){
  const body={previous_event_id:props.item.events.at(-1)?.event_id||null,to_status:d.to_status,note:d.note.trim(),candidate_causes:lines(d.candidate_causes),confirmed_cause:d.confirmed_cause}
  if(d.to_status==='CHANGED')Object.assign(body,{change_summary:d.change_summary,repair_plan:repairPlan(d.plan,d.sampleIds)})
  if(d.to_status==='CLOSED')body.closure_type=d.closure_type
  if(d.to_status==='RETESTED')Object.assign(body,{verification_run_id:d.verification_run_id,verification_kind:props.item.next_action.verification_kind,verification_sample_id:d.verification_sample_id,outcome:d.outcome,evidence_level:d.outcome==='FIXED'?d.evidence_level:'UNVERIFIED',verification_report:d.regression_result.trim()&&d.validation_scope.trim()?{target_eliminated:d.target_eliminated,regression_checked:d.regression_checked,regression_found:d.regression_checked?d.regression_found:null,regression_result:d.regression_result,validation_scope:d.validation_scope,unexcluded_factors:lines(d.unexcluded_factors),regression_sample_ids:lines(d.regression_sample_ids),unseen_sample_ids:lines(d.unseen_sample_ids)}:null})
  emit('update',body)
}
</script>
<template>
  <section class="panel cal-issue" :data-issue-id="item.issue.issue_id"><div class="section-heading"><h3>{{item.issue.title}}</h3><span class="pill">{{issueStatuses[item.status]}}<template v-if="item.closure_type"> · {{issueClosures[item.closure_type]}}</template></span></div>
    <p class="muted">{{issueLayers[item.issue.layer]}} · 负责人 {{item.issue.owner}} · 来源 {{item.issue.source_type}} / {{item.issue.run_id.slice(0,8)}} / {{item.issue.sample_id}} · {{evidenceLevels[item.evidence_level]}}</p><p>{{item.issue.description}}</p><p v-for="(e,index) in item.issue.related_evidence" :key="index">证据：{{e}}</p><p>候选原因：{{item.issue.candidate_causes?.join('；')||'尚未记录'}}</p><p>其他解释：{{item.issue.alternative_explanations||'尚未记录'}}</p><p>下一项检查：{{item.issue.next_check||'尚未记录'}}</p>
    <p v-if="item.issue.observed_count" class="muted">观察到 {{item.issue.observed_count}} / {{item.issue.observed_denominator}} · {{item.issue.sampling_source}}。修复成本：{{item.issue.repair_cost||'未估计'}}。</p>
    <p>排查优先级：{{{CRITICAL:'严重错误，少见也需优先核查',CORE_TASK:'影响核心任务',MINOR:'轻微问题，频次需结合采样分母',UNKNOWN:'证据不足，待排查'}[item.issue.severity||'UNKNOWN']}}；不合成任意权重总分。</p><p class="note">{{issueRoutes[item.issue.layer]}}</p><button v-if="item.status!=='CLOSED'" type="button" class="secondary" @click="emit('navigate',item.issue)">前往对应修复入口</button>
    <ol class="cal-issue-timeline"><li v-for="event in item.events" :key="event.event_id"><strong>{{issueStatuses[event.to_status]}}<template v-if="event.closure_type"> · {{issueClosures[event.closure_type]}}</template></strong> · {{event.actor}}<p>{{event.note}}</p><p v-if="event.candidate_causes?.length">本轮候选：{{event.candidate_causes.join('；')}}</p><p v-if="event.confirmed_cause">目前确认的主因：{{event.confirmed_cause}}（原假设仍保留）</p><p v-if="event.change_summary">实际修改：{{event.change_summary}}</p><p v-if="event.verification_run_id">复测 {{event.verification_kind}} / {{event.verification_run_id.slice(0,8)}} · {{event.outcome}} · {{evidenceLevels[event.evidence_level]}}</p><template v-if="event.verification_report"><p>目标错误{{event.verification_report.target_eliminated?'已消除':'未确认消除'}}；退化检查：{{event.verification_report.regression_result}}</p><p>本次结论范围：{{event.verification_report.validation_scope}}</p><p>未排除因素：{{event.verification_report.unexcluded_factors.join('；')||'未填写'}}</p><p>同类回归 {{event.verification_report.regression_sample_ids.length?'已关联 '+event.verification_report.regression_sample_ids.length+' 题':'未完成独立回归'}} · 未见新题 {{event.verification_report.unseen_sample_ids.length?'已关联 '+event.verification_report.unseen_sample_ids.length+' 题':'未完成'}}</p></template></li></ol>
    <form v-if="d.to_status" @submit.prevent="submit"><label>下一步<select v-model="d.to_status"><option v-for="s in issueTransitions[item.status]" :key="s" :value="s">{{issueStatuses[s]}}</option></select></label><label>判断、依据及未解决因素<textarea v-model="d.note" rows="2" maxlength="3000" required /></label>
      <details><summary>保留本轮假设或改判</summary><label>候选原因 · 每行一个<textarea v-model="d.candidate_causes" rows="2" /></label><label>已确认主因（无足够证据时留空）<textarea v-model="d.confirmed_cause" rows="2" maxlength="2000" /></label></details>
      <template v-if="d.to_status==='CHANGED'"><label>实际修改与差异<textarea v-model="d.change_summary" rows="2" required /></label><h4>复测前固定本轮条件</h4><label>成功条件<textarea v-model="d.plan.success_criteria" rows="2" required /></label><label>目标错误<textarea v-model="d.plan.target_error" rows="2" required /></label><label>潜在退化及容许范围<textarea v-model="d.plan.potential_regressions" rows="2" required /></label><label>验证范围<textarea v-model="d.plan.validation_scope" rows="2" required /></label><label>必须覆盖的题目 ID · 每行一个<textarea v-model="d.sampleIds" rows="2" required /></label><label>目标评分<select v-model="d.plan.expected_verdict"><option :value="null">不预设</option><option value="PASS">PASS</option><option value="FAIL">FAIL（修复误放行）</option></select></label></template>
      <template v-if="d.to_status==='RETESTED'"><p class="note">本问题需要 {{item.next_action.verification_kind}}。复测须在修改记录之后创建，评分有效，覆盖原问题并保留版本依据。</p><label>复测运行或已解封保留验证<select v-model="d.verification_run_id" required><option value="">选择新的运行</option><option v-for="r in runs.filter(r=>r.run_id!==item.issue.run_id)" :key="r.run_id" :value="r.run_id">{{r.run_id.slice(0,8)}} · {{r.status}} · {{r.partition||r.run_type}}</option></select></label><label>对应复测题目 ID<input v-model="d.verification_sample_id" required /></label><label>本轮结果<select v-model="d.outcome"><option value="INCONCLUSIVE">证据不足，暂不确定</option><option value="NOT_FIXED">仍未解决</option><option value="FIXED">证据支持目标问题已修复</option></select></label>
        <label class="check"><input v-model="d.target_eliminated" type="checkbox" />预先声明的目标错误已消除</label><label class="check"><input v-model="d.regression_checked" type="checkbox" />已检查其他错误与潜在退化</label><label v-if="d.regression_checked" class="check"><input v-model="d.regression_found" type="checkbox" />发现不符合容许范围的新增退化</label><label>退化检查的依据与结果<textarea v-model="d.regression_result" rows="2" :required="d.outcome==='FIXED'" /></label><label>结论适用范围<textarea v-model="d.validation_scope" rows="2" :required="d.outcome==='FIXED'" placeholder="只验证原题时明确限定；不同标准研究不能声称 Agent 改善" /></label><label>未排除因素 · 每行一项<textarea v-model="d.unexcluded_factors" rows="2" /></label><details><summary>同类回归与未见题证据</summary><label>同类回归题目 ID · 每行一个<textarea v-model="d.regression_sample_ids" rows="2" /></label><label>未见新题 ID · 每行一个<textarea v-model="d.unseen_sample_ids" rows="2" /></label><p class="muted">题目须在本次运行中有有效评分；基线已经使用过的题不能标为未见。保留题仍须经过专门解封流程。</p><label>本次证据等级<select v-model="d.evidence_level"><option value="SAME_CASE">原题验证</option><option value="REGRESSION">同类回归验证</option><option value="UNSEEN">未见新题验证</option></select></label></details></template>
      <label v-if="d.to_status==='CLOSED'">关闭类型<select v-model="d.closure_type"><option value="FIXED" :disabled="!canFixed">问题已修复（需要已通过验收的复测）</option><option value="FALSE_ALARM">误报已澄清（保留依据）</option><option value="DEFERRED">暂不修复（记录原因）</option></select></label>
      <p class="muted">关闭不等于修复成功；返回成功不等于验收通过；PASS 改成 FAIL 也可能纠正错误评分。</p><button class="secondary" :disabled="disabled||!d.note.trim()">追加进展与判断</button>
    </form>
  </section>
</template>
